import{_ as d,a0 as o,w as l,s as r,ao as t,I as i,x as a,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"Linux 中 4 個簡單的找出進程 ID（PID）的方法 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 中 4 個簡單的找出進程 ID（PID）的方法 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 中 4 個簡單的找出進程 ID（PID）的方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 中 4 個簡單的找出進程 ID（PID）的方法 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171219 4 Easiest Ways To Find Out Process ID (PID) In Linux","title":"Linux 中 4 個簡單的找出進程 ID（PID）的方法","tag":"201802","desc":""},"relativePath":"201802/20171219 4 Easiest Ways To Find Out Process ID (PID) In Linux.md","filePath":"[post].md"}'),c={name:"201802/20171219 4 Easiest Ways To Find Out Process ID (PID) In Linux.md"};function h(u,s,g,k,D,I){const e=o("Link");return l(),r("div",null,[s[16]||(s[16]=t('<h1 id="linux-中-4-個簡單的找出進程-id-pid-的方法" tabindex="-1">Linux 中 4 個簡單的找出進程 ID（PID）的方法 <a class="header-anchor" href="#linux-中-4-個簡單的找出進程-id-pid-的方法" aria-label="Permalink to “Linux 中 4 個簡單的找出進程 ID（PID）的方法”">​</a></h1><p>每個人都知道 PID，究竟什麼是 PID？為什麼你想要 PID？你打算用 PID 做什麼？你腦子裏有同樣的問題嗎？如果是這樣，你就找對地方瞭解這些細節了。</p><p>我們查詢 PID 主要是用來殺死一個沒有響應的程序，它類似於 Windows 任務管理器一樣。 Linux GUI 也提供相同的功能，但 CLI 是執行 <code>kill</code> 操作的有效方法。</p><h3 id="什麼是進程-id" tabindex="-1">什麼是進程 ID? <a class="header-anchor" href="#什麼是進程-id" aria-label="Permalink to “什麼是進程 ID?”">​</a></h3><p>PID 代表<ruby>進程標識號<rt>process identification</rt></ruby>，它在大多數操作系統內核（如 Linux、Unix、macOS 和 Windows）中使用。它是在操作系統中創建時自動分配給每個進程的唯一標識號。一個進程是一個正在運行的程序實例。</p>',5)),i("p",null,[s[1]||(s[1]=i("strong",null,"建議閲讀：",-1)),s[2]||(s[2]=a()),n(e,{href:"https://www.2daygeek.com/check-find-apache-httpd-web-server-uptime-linux/"},{default:p(()=>[...s[0]||(s[0]=[a("如何查看 Apache Web 服務器在 Linux 中的運行時間",-1)])]),_:1})]),s[17]||(s[17]=t(`<p>除了 init 進程外其他所有的進程 ID 每次都會改變，因為 init 始終是系統上的第一個進程，並且是所有其他進程的父進程。它的 PID 是 1。</p><p>PID 默認的最大值是 <code>32768</code>。可以在你的系統上運行 <code>cat /proc/sys/kernel/pid_max</code> 來驗證。在 32 位系統上，<code>32768</code> 是最大值，但是我們可以在 64 位系統上將其設置為最大 2^22（約 4 百萬）內的任何值。</p><p>你可能會問，為什麼我們需要這麼多的 PID？因為我們不能立即重用 PID，這就是為什麼。另外為了防止可能的錯誤。</p><p>系統正在運行的進程的 PID 可以通過使用 <code>pidof</code>、<code>pgrep</code>、<code>ps</code> 和 <code>pstree</code> 命令找到。</p><h3 id="方法-1-使用-pidof-命令" tabindex="-1">方法 1：使用 pidof 命令 <a class="header-anchor" href="#方法-1-使用-pidof-命令" aria-label="Permalink to “方法 1：使用 pidof 命令”">​</a></h3><p><code>pidof</code> 用於查找正在運行的程序的進程 ID。它在標準輸出上打印這些 id。為了演示，我們將在 Debian 9（stretch）系統中找出 Apache2 的進程 ID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pidof apache2</span></span>
<span class="line"><span>3754 2594 2365 2364 2363 2362 2361</span></span></code></pre></div><p>從上面的輸出中，你可能會遇到難以識別進程 ID 的問題，因為它通過進程名稱顯示了所有的 PID（包括父進程和子進程）。因此，我們需要找出父 PID（PPID），這是我們要查找的。它可能是第一個數字。在本例中，它是 <code>3754</code>，並按降序排列。</p><h3 id="方法-2-使用-pgrep-命令" tabindex="-1">方法 2：使用 pgrep 命令 <a class="header-anchor" href="#方法-2-使用-pgrep-命令" aria-label="Permalink to “方法 2：使用 pgrep 命令”">​</a></h3><p><code>pgrep</code> 遍歷當前正在運行的進程，並將符合選擇條件的進程 ID 列到標準輸出中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pgrep apache2</span></span>
<span class="line"><span>2361</span></span>
<span class="line"><span>2362</span></span>
<span class="line"><span>2363</span></span>
<span class="line"><span>2364</span></span>
<span class="line"><span>2365</span></span>
<span class="line"><span>2594</span></span>
<span class="line"><span>3754</span></span></code></pre></div><p>這也與上面的輸出類似，但是它將結果從小到大排序，這清楚地説明父 PID 是最後一個。在本例中，它是 <code>3754</code>。</p><p><strong>注意：</strong> 如果你有多個進程的進程 ID，那麼在使用 <code>pidof</code> 和 <code>pgrep</code> 識別父進程 ID 時就可能不會很順利。</p><h3 id="方法-3-使用-pstree-命令" tabindex="-1">方法 3：使用 pstree 命令 <a class="header-anchor" href="#方法-3-使用-pstree-命令" aria-label="Permalink to “方法 3：使用 pstree 命令”">​</a></h3><p><code>pstree</code> 將運行的進程顯示為一棵樹。樹的根是某個 pid，如果省略了 pid 參數，那麼就是 init。如果在 <code>pstree</code> 命令中指定了用户名，則顯示相應用户擁有的所有進程。</p><p><code>pstree</code> 會將相同的分支放在方括號中，並添加重複計數的前綴來可視化地合併到一起。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pstree -p | grep &quot;apache2&quot;</span></span>
<span class="line"><span> |- apache2(3754) -|-apache2(2361)</span></span>
<span class="line"><span> | |-apache2(2362)</span></span>
<span class="line"><span> | |-apache2(2363)</span></span>
<span class="line"><span> | |-apache2(2364)</span></span>
<span class="line"><span> | |-apache2(2365)</span></span>
<span class="line"><span> | \`-apache2(2594)</span></span></code></pre></div><p>要單獨獲取父進程，請使用以下格式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pstree -p | grep &quot;apache2&quot; | head -1</span></span>
<span class="line"><span> |- apache2(3754) -|-apache2(2361)</span></span></code></pre></div><p><code>pstree</code> 命令非常簡單，因為它分別隔離了父進程和子進程，但這在使用 <code>pidof</code> 和 <code>pgrep</code> 時命令不容易做到。</p><h3 id="方法-4-使用-ps-命令" tabindex="-1">方法 4：使用 ps 命令 <a class="header-anchor" href="#方法-4-使用-ps-命令" aria-label="Permalink to “方法 4：使用 ps 命令”">​</a></h3><p><code>ps</code> 顯示活動進程的選擇信息。它顯示進程 ID（<code>pid</code>=PID）、與進程關聯的終端（<code>tname</code>=TTY）、以 <code>[DD-]hh:mm:ss</code> 格式（<code>time</code>=TIME）顯示的累計 CPU 時間、以及執行名（<code>ucmd</code> = CMD）。輸出默認是未排序的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ps aux | grep &quot;apache2&quot;</span></span>
<span class="line"><span>www-data 2361 0.0 0.4 302652 9732 ? S 06:25 0:00 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>www-data 2362 0.0 0.4 302652 9732 ? S 06:25 0:00 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>www-data 2363 0.0 0.4 302652 9732 ? S 06:25 0:00 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>www-data 2364 0.0 0.4 302652 9732 ? S 06:25 0:00 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>www-data 2365 0.0 0.4 302652 8400 ? S 06:25 0:00 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>www-data 2594 0.0 0.4 302652 8400 ? S 06:55 0:00 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>root 3754 0.0 1.4 302580 29324 ? Ss Dec11 0:23 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>root 5648 0.0 0.0 12784 940 pts/0 S+ 21:32 0:00 grep apache2</span></span></code></pre></div><p>從上面的輸出中，我們可以根據進程的啓動日期輕鬆地識別父進程 ID（PPID）。在此例中，apache2 啓動於 <code>Dec 11</code>，它是父進程，其他的是子進程。apache2 的 PID 是 <code>3754</code>。</p><hr>`,25)),i("p",null,[s[4]||(s[4]=a("via: ",-1)),n(e,{href:"https://www.2daygeek.com/how-to-check-find-the-process-id-pid-ppid-of-a-running-program-in-linux/"},{default:p(()=>[...s[3]||(s[3]=[a("https://www.2daygeek.com/how-to-check-find-the-process-id-pid-ppid-of-a-running-program-in-linux/",-1)])]),_:1})]),i("p",null,[s[8]||(s[8]=a("作者：",-1)),n(e,{href:"https://www.2daygeek.com/author/magesh/"},{default:p(()=>[...s[5]||(s[5]=[a("Magesh Maruthamuthu",-1)])]),_:1}),s[9]||(s[9]=a(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:p(()=>[...s[6]||(s[6]=[a("geekpi",-1)])]),_:1}),s[10]||(s[10]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[13]||(s[13]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:p(()=>[...s[12]||(s[12]=[a("Linux中國",-1)])]),_:1}),s[15]||(s[15]=a(" 榮譽推出",-1))])])}const m=d(c,[["render",h]]);export{P as __pageData,m as default};
